// Liest die Antwort der KI (JSON) und prüft, ob eine Quelle da ist.
const quelle = $('Style-Guide & Regeln').first().json;
if (!quelle.quelltext || quelle.quelltext.length < 200) {
  throw new Error('Keine oder zu kurze Quelle/Abschrift gefunden. Bitte Abschrift prüfen.');
}

let roh = $input.first().json.text || '';
roh = roh.replace(/```json/gi, '').replace(/```/g, '').trim();

let fakten;
try {
  fakten = JSON.parse(roh);
} catch (e) {
  throw new Error('Die KI hat kein gültiges JSON geliefert (Fakten). Antwort: ' + roh.slice(0, 300));
}

// Fehlende Felder mit leeren Listen auffüllen
for (const feld of ['kernaussagen', 'fakten', 'woertliche_zitate', 'nicht_verwenden', 'unsicher']) {
  if (!Array.isArray(fakten[feld])) fakten[feld] = [];
}

return [{ json: { fakten } }];

parameters.text:
=Du bist Social-Media-Redakteur bei Wissensblitz KI. Schreibe aus den FAKTEN die Entwürfe.

{{ $('Style-Guide & Regeln').first().json.styleGuide }}

STRENGE REGELN:
1. Verwende NUR Inhalte aus FAKTEN, KERNAUSSAGEN und WÖRTLICHE ZITATE. Erfinde keine Zahlen, Namen oder Beispiele mit Zahlen.
2. Wörtliche Zitate übernimmst du exakt, Zeichen für Zeichen, in „deutschen Anführungszeichen“.
3. Inhalte aus NICHT VERWENDEN dürfen in keinem Text vorkommen, auch nicht umschrieben.
4. Steht eine Aussage unter UNSICHER, schreibe direkt dahinter [PRÜFEN].
5. Alle Texte auf Deutsch, per Du.

FORMATE:
- instagram: Bildunterschrift, 80–150 Wörter, starker erster Satz, am Ende 5–8 Hashtags.
- linkedin: 150–250 Wörter, erster Satz macht neugierig, kurze Absätze, am Ende eine Frage an die Leser.
- x_thread: Liste mit 4–6 Tweets, jeder höchstens 270 Zeichen, erster Tweet mit ⚡.
- newsletter: 80–120 Wörter, persönlich, mit Hinweis auf das Video.
- video_skript: Kurzvideo 45–60 Sekunden (ca. 130 Wörter). Aufbau: HOOK (erste 3 Sekunden), 3 Punkte, AUFRUF.
- email: Zusammenfassung mit "betreff" (max. 60 Zeichen) und "text" (120–180 Wörter, 3 Stichpunkte, Link-Hinweis).

Antworte NUR mit gültigem JSON, ohne Erklärung:
{"instagram": "", "linkedin": "", "x_thread": ["", ""], "newsletter": "", "video_skript": "", "email": {"betreff": "", "text": ""}}

TITEL: {{ $('Style-Guide & Regeln').first().json.titel }}
VIDEO-LINK: {{ $('Style-Guide & Regeln').first().json.videoUrl }}

KERNAUSSAGEN: {{ JSON.stringify($json.fakten.kernaussagen) }}
FAKTEN: {{ JSON.stringify($json.fakten.fakten) }}
WÖRTLICHE ZITATE: {{ JSON.stringify($json.fakten.woertliche_zitate) }}
UNSICHER: {{ JSON.stringify($json.fakten.unsicher) }}
NICHT VERWENDEN: {{ JSON.stringify($json.fakten.nicht_verwenden) }}

