// Prüft die Entwürfe gegen die Quelle und baut die Telegram-Nachrichten.
const quelle = $('Style-Guide & Regeln').first().json;
const fakten = $('Fakten lesen').first().json.fakten;

let roh = $input.first().json.text || '';
roh = roh.replace(/```json/gi, '').replace(/```/g, '').trim();
let e;
try {
  e = JSON.parse(roh);
} catch (err) {
  throw new Error('Die KI hat kein gültiges JSON geliefert (Entwürfe). Antwort: ' + roh.slice(0, 300));
}

// Text vereinheitlichen, damit Leerzeichen und Anführungszeichen den Vergleich nicht stören
const norm = (t) => String(t || '')
  .replace(/[„“”"«»‚‘’']/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const quellNorm = norm(quelle.quelltext);

const xThread = Array.isArray(e.x_thread) ? e.x_thread : [String(e.x_thread || '')];
const email = e.email || {};
const alleTexte = [e.instagram, e.linkedin, xThread.join('\n'), e.newsletter, e.video_skript, email.betreff, email.text].join('\n');

const hinweise = [];

// 1) Zitat-Prüfung: Jedes Zitat in „...“ muss wörtlich in der Quelle stehen
const zitate = [...alleTexte.matchAll(/„([^“”"]{8,})[“”"]/g)].map(m => m[1]);
for (const z of zitate) {
  if (!quellNorm.includes(norm(z))) hinweise.push('Zitat nicht wörtlich in der Quelle: „' + z + '“');
}

// 2) Gesperrtes Material darf nicht vorkommen
for (const sperre of fakten.nicht_verwenden) {
  const stueck = norm(sperre).split(' ').slice(0, 6).join(' ');
  if (stueck.length > 10 && norm(alleTexte).includes(stueck)) {
    hinweise.push('Gesperrtes Material verwendet: ' + sperre);
  }
}

// 3) X-Thread: Länge pro Tweet prüfen
xThread.forEach((t, i) => {
  if (t.length > 280) hinweise.push('Tweet ' + (i + 1) + ' ist zu lang (' + t.length + ' Zeichen)');
});

// 4) Unsichere Stellen zählen
const pruefen = (alleTexte.match(/\[PRÜFEN\]/g) || []).length;

const kopf = '⚡ NEUE ENTWÜRFE: ' + quelle.titel + '\n'
  + (quelle.videoUrl ? 'Video: ' + quelle.videoUrl + '\n' : '')
  + (quelle.bild ? 'Bild: ' + quelle.bild + '\n' : '')
  + '\nMarkiert mit [PRÜFEN]: ' + pruefen
  + '\nAutomatische Prüfung: ' + (hinweise.length ? '⚠️ ' + hinweise.length + ' Hinweis(e)\n- ' + hinweise.join('\n- ') : '✅ keine Auffälligkeiten');

const nachrichten = [
  kopf,
  '📸 INSTAGRAM\n\n' + e.instagram,
  '💼 LINKEDIN\n\n' + e.linkedin,
  '🐦 X-THREAD\n\n' + xThread.map((t, i) => (i + 1) + '/ ' + t).join('\n\n'),
  '📰 NEWSLETTER\n\n' + e.newsletter,
  '🎬 KURZVIDEO-SKRIPT\n\n' + e.video_skript,
  '✉️ E-MAIL\nBetreff: ' + email.betreff + '\n\n' + email.text,
];

return nachrichten.map(n => ({
  json: {
    nachricht: n.slice(0, 4000),
    entwuerfe: e,
    hinweise,
    pruefenAnzahl: pruefen,
  }
}));
